using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
static class NotificationLifecycleSpecs
{
 private sealed class Handler:HttpMessageHandler{
  public List<string> Bodies=[];public Queue<(HttpStatusCode,string)> Replies=[];
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Bodies.Add(await request.Content!.ReadAsStringAsync(token));var r=Replies.Count>0?Replies.Dequeue():(HttpStatusCode.OK,"{\"ok\":true,\"result\":{\"message_id\":42}}");return new(r.Item1){Content=new StringContent(r.Item2,Encoding.UTF8,"application/json")};}
 }
 public static async Task Run(string root,Action<string,bool> check){
  var folder=Path.Combine(root,"notification-lifecycle");Directory.CreateDirectory(folder);var factory=new DatabaseFactory(new AppSettings{SqlitePath=Path.Combine(folder,"db.sqlite")});await factory.InitializeAsync();
  var now=new DateTime(2026,10,30,12,0,0);var job=new SqlBackupJob{Title="Backup",Host="hyperv.local",DeviceId=null,DeadlineMinutes=600,CompletionTimes="10:00;18:00",GraceMinutes=30,Days=127,MonitoringSince=now.AddDays(-60)};
  ReportEvent Report(DateTime at,int slot=600,string description="Path is too long")=>new(){JobId=job.Id,Provider="Veeam",Result=BackupResult.Failed,Severity=Severity.Warning,Task="Backup failed",Description=description,IsPending=false,ScheduledSlotMinutes=slot,OccurredAt=at,ReceivedAt=at};
  await using(var db=factory.Create()){db.Jobs.Add(job);await db.SaveChangesAsync();for(int i=0;i<20;i++){var r=Report(now.AddDays(-20+i));db.Reports.Add(r);await db.SaveChangesAsync();db.Incidents.Add(new(){ReportId=r.Id,CreatedAt=r.ReceivedAt,Severity=r.Severity,Source="Veeam",Title=r.Task,Details="PRIVATE-MAIL-BODY"});}await db.SaveChangesAsync();}
  ReportEvent[] reports;Incident[] incidents;await using(var db=factory.Create()){reports=await db.Reports.AsNoTracking().ToArrayAsync();incidents=await db.Incidents.AsNoTracking().ToArrayAsync();}
  var grouped=BackupIncidentLifecycle.Group(incidents,reports,[job]);check("Twenty same backup failures form one active incident with count",grouped.Length==1&&grouped[0].Count==20&&grouped[0].FirstAt==now.AddDays(-20)&&grouped[0].LastAt==now.AddDays(-1));
  var extra=Report(now.AddHours(-1),1080);extra.Id=9001;var otherCause=Report(now.AddHours(-1),600,"Access denied");otherCause.Id=9002;
  var expanded=BackupIncidentLifecycle.Group(incidents.Concat([new(){Id=9001,ReportId=9001,Severity=Severity.Warning},new(){Id=9002,ReportId=9002,Severity=Severity.Warning}]),reports.Concat([extra,otherCause]),[job]);check("Different backup slot and cause remain separate",expanded.Length==3);
  var pathA=Report(now,600,@"Path C:\backup\daily-20261029\snapshot-a.avhdx is too long");var pathB=Report(now,600,@"Path C:\backup\daily-20261030\snapshot-b.avhdx is too long");check("Path-too-long episodes group across changing daily file names",BackupIncidentLifecycle.Key(job,pathA)==BackupIncidentLifecycle.Key(job,pathB));
  var foreignDevice=Report(now);foreignDevice.DeviceId=99;check("Backup signature separates different devices on a shared job",BackupIncidentLifecycle.Key(job,foreignDevice)!=BackupIncidentLifecycle.Key(job,reports[0]));
  var datedA=Report(now,600,"Path at 2026-10-29 10:00:00 is too long");var datedB=Report(now,600,"Path at 2026-10-30 10:00:00 is too long");check("Only varying timestamps normalize in backup signature",BackupIncidentLifecycle.Key(job,datedA)==BackupIncidentLifecycle.Key(job,datedB));
  var store=new NetworkStore(Path.Combine(folder,"network"));var settings=new AppSettings{MonitoringEnabled=false};
  await ApplicationNotifications.CaptureAsync(factory,store,settings,now,default);check("Repeated backup fault queues one grouped Telegram alert",store.State(s=>s.Notifications.Count(n=>n.EntityKey.StartsWith("backup-incident:")))==1);check("Backup Telegram excludes raw private mail body",store.State(s=>s.Notifications.Where(n=>n.EntityKey.StartsWith("backup-incident:")).All(n=>!n.Title.Contains("PRIVATE-MAIL-BODY"))));
  await ApplicationNotifications.CaptureAsync(factory,store,settings,now.AddMinutes(1),default);check("Unchanged grouped backup does not queue daily spam",store.State(s=>s.Notifications.Count(n=>n.EntityKey.StartsWith("backup-incident:")))==1);
  async Task InvalidSuccess(ReportEvent success,string label){await using var db=factory.Create();db.Reports.Add(success);await db.SaveChangesAsync();var rows=await db.Reports.AsNoTracking().ToArrayAsync();await BackupIncidentLifecycle.ReconcileAsync(db,rows,[job],now,default);check(label,await db.Incidents.CountAsync(i=>!i.Closed)==20);db.Reports.Remove(success);await db.SaveChangesAsync();}
  ReportEvent Success(DateTime at,int slot=600)=>new(){JobId=job.Id,Provider="Veeam",Result=BackupResult.Success,Severity=Severity.Info,IsPending=false,ScheduledSlotMinutes=slot,OccurredAt=at,ReceivedAt=at};
  var foreignSuccess=Success(now);foreignSuccess.DeviceId=99;await InvalidSuccess(foreignSuccess,"Success on another device cannot close failures");
  await InvalidSuccess(Success(now,1080),"Success in another scheduled run cannot close failures");await InvalidSuccess(Success(now.AddDays(-30)),"Older success cannot close later failures");await InvalidSuccess(Success(now.AddDays(1)),"Future success cannot close failures");var pending=Success(now);pending.IsPending=true;await InvalidSuccess(pending,"Unparsed pending success cannot close failures");var unknown=Success(now);unknown.Result=BackupResult.Unknown;await InvalidSuccess(unknown,"Unknown result never closes backup failures");var warning=Success(now);warning.Severity=Severity.Warning;await InvalidSuccess(warning,"Success with warning cannot claim healthy recovery");
  await using(var db=factory.Create()){db.Reports.Add(Success(now));await db.SaveChangesAsync();}
  await ApplicationNotifications.CaptureAsync(factory,store,settings,now,default);
  await using(var db=factory.Create()){check("Fresh matching success closes all twenty historical failures",await db.Incidents.CountAsync(i=>!i.Closed)==0);check("Recovery preserves every original incident and report",await db.Incidents.CountAsync()==20&&await db.Reports.CountAsync()==21);}
  check("Grouped backup recovery is queued once with shared identity",store.State(s=>s.Notifications.Count(n=>n.EntityKey.StartsWith("backup-incident:")&&n.Transition.StartsWith("ЗАКРЫТО")))==1);
  await ApplicationNotifications.CaptureAsync(factory,store,settings,now.AddMinutes(1),default);check("Recovered backup does not repeatedly queue recovery",store.State(s=>s.Notifications.Count(n=>n.EntityKey.StartsWith("backup-incident:")&&n.Transition.StartsWith("ЗАКРЫТО")))==1);
  var device=new Device{Id=7,Name="Hyper-V office",Host="192.168.50.3"};var devices=new Dictionary<int,Device>{{7,device}};job.DeviceId=7;var jobs=new Dictionary<int,SqlBackupJob>{{job.Id,job}};
  check("Agent journal notifications resolve friendly device and address",NotificationSubjects.Network(new(){EntityKey="journal:7:abc:recovery"},devices,jobs).Contains("Hyper-V office · 192.168.50.3"));
  check("Backup schedule notices include job and related device",NotificationSubjects.Network(new(){EntityKey="schedule:"+job.Id+":600"},devices,jobs).Contains("Hyper-V office")&&NotificationSubjects.Network(new(){EntityKey="schedule:"+job.Id+":600"},devices,jobs).Contains("Задание: Backup"));
  await using(var db=factory.Create()){db.Devices.Add(device);foreach(var at in new[]{now.AddHours(1),now.AddHours(2)}){var r=Report(at);r.DeviceId=7;db.Reports.Add(r);await db.SaveChangesAsync();db.Incidents.Add(new(){ReportId=r.Id,Severity=Severity.Warning,Title=r.Task,CreatedAt=at});}await db.SaveChangesAsync();}
  int groupIncident;await using(var db=factory.Create()){var deviceProblems=await DeviceProblems.OpenAsync(db,7);check("Device card shows one backup problem with repeat count",deviceProblems.Length==1&&deviceProblems[0].Incident.Title.Contains("повторов: 2"));groupIncident=deviceProblems.Single().Incident.Id;}
  await DeviceProblems.ResolveAsync(factory,new(7,groupIncident));await using(var db=factory.Create())check("Resolving grouped device problem closes every matching occurrence atomically",await db.Incidents.CountAsync(i=>!i.Closed)==0);
  var context=NotificationSubjects.Incident(new(),reports[0],devices,jobs);check("Ordinary mail incident resolves device through backup job",context.Contains("Hyper-V office"));check("Incident formatter includes context without raw mail body",TelegramSender.Format(new(){Details="PRIVATE-MAIL-BODY"},context).Contains("Hyper-V office")&&!TelegramSender.Format(new(){Details="PRIVATE-MAIL-BODY"},context).Contains("PRIVATE-MAIL-BODY"));
  var legacy=new NetworkState();for(int i=0;i<20;i++)legacy.Notifications.Add(new(){EntityKey="schedule:42:600",CreatedAt=DateTime.UtcNow.AddDays(-i),Severity=Severity.Warning});legacy.Notifications.Add(new(){EntityKey="schedule:43:600",Severity=Severity.Critical});BackupIncidentLifecycle.CoalescePending(legacy);check("Legacy queued daily backup duplicates coalesce without hiding other jobs",legacy.Notifications.Count(n=>n.HandledAt==null)==2&&legacy.Notifications.Count==21);
  var tg=new TelegramSettings{Enabled=true,ChatId="-100123",ProtectedToken="fixture",Critical=true,Warning=true};var sent=new List<int?>();int sequence=100;Task<int> Send(string text,int? reply,CancellationToken token){sent.Add(reply);return Task.FromResult(++sequence);}
  var threadsDir=Path.Combine(folder,"threads");var threads=new TelegramMessageThreads(threadsDir);
  await threads.SendAsync(tg,"open-1","agent:7:cpu",false,"bad",default,Send);await new TelegramMessageThreads(threadsDir).SendAsync(tg,"close-1","agent:7:cpu:recovery",true,"ok",default,Send);check("Recovery after server restart replies to original message",sent.Count==2&&sent[0]==null&&sent[1]==101);
  await threads.SendAsync(tg,"close-1","agent:7:cpu",true,"ok",default,Send);check("Persisted receipt suppresses duplicate event retry",sent.Count==2);
  await threads.SendAsync(tg,"open-2","agent:7:cpu",false,"bad again",default,Send);await threads.SendAsync(tg,"close-2","agent:7:cpu",true,"ok again",default,Send);check("New incident cycle replies to new opening",sent[^1]==103);
  await threads.SendAsync(tg,"unknown-recovery","unknown",true,"ok",default,Send);check("Legacy recovery without receipt sends standalone",sent[^1]==null);
  await threads.SendAsync(tg,"new-open","another",false,"bad",default,Send);tg.ChatId="-100456";await threads.SendAsync(tg,"new-close","another",true,"ok",default,Send);check("Reply receipts never cross Telegram destinations",sent[^1]==null);tg.ChatId="-100123";await threads.SendAsync(tg,"bot-close","another",true,"ok",default,Send,"different-bot");check("Reply receipts never cross bots",sent[^1]==null);
  check("Router audit recovery correlates with prior summary",TelegramMessageThreads.IssueKey("router-audit:7:summary:opening")==TelegramMessageThreads.IssueKey("router-audit:7:summary:recovery"));
  var handler=new Handler();using var client=new HttpClient(handler);const string secret="123456:ABCDEFGHIJKLMNOPQRSTUVWXYZ12345";var id=await TelegramSender.SendMessageAsync(tg,"green",default,client,secret,101);using(var json=JsonDocument.Parse(handler.Bodies.Last()))check("Telegram API uses reply_parameters with safe missing-reply fallback",id==42&&json.RootElement.GetProperty("reply_parameters").GetProperty("message_id").GetInt32()==101&&json.RootElement.GetProperty("reply_parameters").GetProperty("allow_sending_without_reply").GetBoolean());
  handler.Replies.Enqueue((HttpStatusCode.BadRequest,"{\"ok\":false,\"description\":\"Bad Request: message to be replied not found\"}"));handler.Replies.Enqueue((HttpStatusCode.OK,"{\"ok\":true,\"result\":{\"message_id\":43}}"));await TelegramSender.SendMessageAsync(tg,"green",default,client,secret,101);using(var json=JsonDocument.Parse(handler.Bodies.Last()))check("Deleted original message falls back to standalone recovery",!json.RootElement.TryGetProperty("reply_parameters",out _));
  var count=handler.Bodies.Count;handler.Replies.Enqueue((HttpStatusCode.Forbidden,"{\"ok\":false}"));bool denied=false;try{await TelegramSender.SendMessageAsync(tg,"green",default,client,secret,101);}catch(InvalidOperationException e){denied=e.Message.Contains("403")&&!e.Message.Contains(secret);}check("Telegram denial does not cause fallback duplicate or expose token",denied&&handler.Bodies.Count==count+1);
 }
}
